const Tag = ({c}) => <div style={{fontSize:11,fontWeight:700,letterSpacing:3,textTransform:'uppercase',color:'var(--gold)',marginBottom:14}}>{c}</div>
const H1c = ({c}) => <div style={{fontSize:'clamp(2.6rem,6vw,5rem)',fontWeight:700,lineHeight:1.02,letterSpacing:-1,marginBottom:16,background:'linear-gradient(135deg,#F5E070,#C9A84C,#1FD47E)',WebkitBackgroundClip:'text',WebkitTextFillColor:'transparent',backgroundClip:'text',textAlign:'center',fontFamily:"'Cormorant Garamond', serif",filter:'drop-shadow(0 0 28px rgba(201,168,76,.35))'}}>{c}</div>
const H2c = ({c}) => <div style={{fontSize:'clamp(1.4rem,2.8vw,2.1rem)',fontWeight:800,lineHeight:1.15,marginBottom:14,color:'var(--text)',textAlign:'center'}}>{c}</div>
const Subc = ({c}) => <div style={{fontSize:'clamp(.9rem,1.6vw,1.1rem)',color:'var(--dim)',maxWidth:650,textAlign:'center',lineHeight:1.65,marginBottom:22}}>{c}</div>

function IconBadge({Ico,col='#B8952A'}) {
  return (
    <div style={{width:44,height:44,borderRadius:12,display:'flex',alignItems:'center',justifyContent:'center',marginBottom:12,
      background:`${col}1a`,border:`1px solid ${col}40`}}>
      {Ico ? <Ico stroke={col} size={22}/> : null}
    </div>
  )
}
function Card({icon,title,body,col='#B8952A'}) {
  const isComp = typeof icon === 'function'
  return (
    <motion.div variants={itemAnim} whileHover={{y:-6,borderColor:'rgba(184,149,42,.42)',transition:{duration:.16}}}
      style={{background:'rgba(5,11,24,.80)',backdropFilter:'blur(14px)',border:'1px solid rgba(201,168,76,.18)',borderRadius:16,padding:'22px 18px',flex:1,minWidth:188,maxWidth:285,position:'relative',overflow:'hidden',boxShadow:'0 0 24px rgba(201,168,76,.05)'}}>
      <div style={{position:'absolute',top:0,left:0,right:0,height:2,background:'linear-gradient(90deg,var(--gold),var(--green2))',boxShadow:'0 0 10px rgba(201,168,76,.5)'}}/>
      {isComp ? <IconBadge Ico={icon} col={col}/> : <div style={{fontSize:'1.9rem',marginBottom:11}}>{icon}</div>}
      <div style={{fontWeight:700,marginBottom:7,fontSize:'.97rem'}}>{title}</div>
      <div style={{fontSize:'.84rem',color:'var(--dim)',lineHeight:1.55}}>{body}</div>
    </motion.div>
  )
}
function Stat({n,l}) {
  return (
    <motion.div variants={itemAnim} style={{textAlign:'center'}}>
      <div style={{fontSize:'clamp(1.8rem,3.8vw,2.9rem)',fontWeight:900,color:'var(--gold)'}}>{n}</div>
      <div style={{fontSize:'.79rem',color:'var(--dim)',marginTop:4}}>{l}</div>
    </motion.div>
  )
}
function Scene({children}) {
  return (
    <motion.div variants={sceneIn} initial="initial" animate="animate" exit="exit"
      style={{position:'absolute',inset:0,display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',padding:'76px 44px 56px',overflowY:'auto',background:'transparent'}}>
      {children}
    </motion.div>
  )
}

