// ── HashChain — illustration of linked SHA-256 entries ──
function HashChain({t}) {
  const blocks = [
    {n:1, prev:'0000…', hash:'7c1e…'},
    {n:2, prev:'7c1e…', hash:'a3f9…'},
    {n:3, prev:'a3f9…', hash:'52d0…'},
  ]
  return (
    <div style={{display:'flex',alignItems:'center',justifyContent:'center',flexWrap:'wrap',gap:0,marginBottom:6}}>
      {blocks.map((b,i)=>(
        <div key={b.n} style={{display:'flex',alignItems:'center'}}>
          <motion.div initial={{opacity:0,y:16}} animate={{opacity:1,y:0}} transition={{delay:.25+i*.22,...spring}}
            style={{background:'rgba(5,11,24,.85)',border:'1px solid rgba(201,168,76,.28)',borderRadius:14,padding:'12px 16px',minWidth:150,textAlign:'left',fontFamily:"ui-monospace,'SF Mono',Menlo,monospace",boxShadow:'0 0 22px rgba(201,168,76,.06)'}}>
            <div style={{fontFamily:"'DM Sans',sans-serif",fontWeight:700,fontSize:'.86rem',color:'var(--text)',marginBottom:6}}>{t.entry} {b.n}</div>
            <div style={{fontSize:'.72rem',color:'var(--dim)'}}>{t.prev}: <span style={{color:'#E8C547'}}>{b.prev}</span></div>
            <div style={{fontSize:'.72rem',color:'var(--dim)'}}>{t.hash}: <span style={{color:'#1FD47E'}}>{b.hash}</span></div>
          </motion.div>
          {i<blocks.length-1 && (
            <motion.div initial={{opacity:0}} animate={{opacity:1}} transition={{delay:.4+i*.22}}
              style={{padding:'0 8px',color:'var(--gold)',display:'flex',alignItems:'center'}}>
              <Icons.link size={20}/>
            </motion.div>
          )}
        </div>
      ))}
    </div>
  )
}

